(window.AUDIO_PAK = window.AUDIO_PAK || {})["een-gesprek-met-de-leraar"] = {"verteller|-10%|het rapport": "data:audio/mpeg;base64,", "verteller|-10%|het cijfer": "data:audio/mpeg;base64,", "verteller|-10%|rekenen": "data:audio/mpeg;base64,", "verteller|-10%|lezen": "data:audio/mpeg;base64,", "verteller|-10%|het huiswerk": "data:audio/mpeg;base64,", "verteller|-10%|de ouderavond": "data:audio/mpeg;base64,", "verteller|-10%|oefenen": "data:audio/mpeg;base64,", "verteller|-10%|Hoe gaat het met mijn zoon?": "data:audio/mpeg;base64,", "verteller|-10%|Hij is goed in rekenen.": "data:audio/mpeg;base64,", "verteller|-10%|Lezen is nog moeilijk.": "data:audio/mpeg;base64,", "verteller|-10%|Hij moet thuis oefenen.": "data:audio/mpeg;base64,", "verteller|-10%|Heeft hij huiswerk?": "data:audio/mpeg;base64,", "tom|-10%|Goedenavond, fijn dat u er bent.": "data:audio/mpeg;base64,", "tom|-10%|Goed! Hij is goed in rekenen. Kijk, een acht.": "data:audio/mpeg;base64,", "tom|-10%|Lezen is nog moeilijk. Hij moet thuis oefenen.": "data:audio/mpeg;base64,", "tom|-10%|Lees elke dag samen tien minuten.": "data:audio/mpeg;base64,", "verteller|-10%|zich concentreren": "data:audio/mpeg;base64,", "verteller|-10%|pesten": "data:audio/mpeg;base64,", "verteller|-10%|verlegen": "data:audio/mpeg;base64,", "verteller|-10%|de vriendjes": "data:audio/mpeg;base64,", "verteller|-10%|de klasgenoot": "data:audio/mpeg;base64,", "verteller|-10%|de vooruitgang": "data:audio/mpeg;base64,", "verteller|-10%|Ze kan zich goed concentreren.": "data:audio/mpeg;base64,", "verteller|-10%|Ze is een beetje verlegen.": "data:audio/mpeg;base64,", "verteller|-10%|Heeft ze vriendjes in de klas?": "data:audio/mpeg;base64,", "verteller|-10%|Wordt ze gepest?": "data:audio/mpeg;base64,", "verteller|-10%|Ik zie veel vooruitgang.": "data:audio/mpeg;base64,", "tom|-10%|Uw dochter doet goed haar best.": "data:audio/mpeg;base64,", "tom|-10%|Ja, heel goed. Maar ze is een beetje verlegen.": "data:audio/mpeg;base64,", "tom|-10%|Ja, ze speelt vaak met Sara en Lina.": "data:audio/mpeg;base64,", "tom|-10%|Dank u dat u dat zegt. Ik let er goed op.": "data:audio/mpeg;base64,", "tom|-10%|Praat met haar over school. En nodig eens een klasgenoot uit.": "data:audio/mpeg;base64,", "tom|-10%|Ja, veel! Vooral in taal.": "data:audio/mpeg;base64,", "verteller|-10%|de zorg": "data:audio/mpeg;base64,", "verteller|-10%|de extra hulp": "data:audio/mpeg;base64,", "verteller|-10%|het advies": "data:audio/mpeg;base64,", "verteller|-10%|Mijn zoon is goed in rekenen.": "data:audio/mpeg;base64,", "verteller|-10%|Lezen vindt hij nog moeilijk.": "data:audio/mpeg;base64,", "verteller|-10%|We lezen elke dag samen.": "data:audio/mpeg;base64,", "verteller|-10%|Ik maak me zorgen over mijn dochter.": "data:audio/mpeg;base64,", "verteller|-10%|Krijgt hij extra hulp?": "data:audio/mpeg;base64,", "tom|-10%|Goedemiddag. Waar wilt u over praten?": "data:audio/mpeg;base64,", "tom|-10%|Wat is er aan de hand?": "data:audio/mpeg;base64,", "tom|-10%|Sinds wanneer merkt u dat?": "data:audio/mpeg;base64,", "tom|-10%|Wat doet u thuis?": "data:audio/mpeg;base64,", "tom|-10%|Ik kan extra hulp regelen. Is dat goed?": "data:audio/mpeg;base64,", "tom|-10%|Zullen we over twee weken weer praten?": "data:audio/mpeg;base64,", "fatima|+0%|Meester, ik maak me zorgen. Adam wil niet meer naar school.": "data:audio/mpeg;base64,", "tom|+0%|Dank u dat u het zegt. Weet u waarom?": "data:audio/mpeg;base64,", "fatima|+0%|Hij zegt dat de kinderen hem uitlachen om zijn Nederlands.": "data:audio/mpeg;base64,", "tom|+0%|Dat is niet goed. Ik ga morgen met de klas praten over pesten.": "data:audio/mpeg;base64,", "fatima|+0%|Kan hij ook extra hulp krijgen bij taal?": "data:audio/mpeg;base64,", "tom|+0%|Ja, twee keer per week krijgt hij extra les in een klein groepje.": "data:audio/mpeg;base64,", "fatima|+0%|Zullen we over twee weken weer praten?": "data:audio/mpeg;base64,", "tom|+0%|Goed idee. Ik stuur u een uitnodiging.": "data:audio/mpeg;base64,", "tom|-10%|Heeft u een vraag of een zorg? Stuur mij een bericht.": "data:audio/mpeg;base64,", "verteller|-10%|Beste meester, ik maak me zorgen over Adam. Sinds een week is hij verdrietig. Kunnen we praten? Met vriendelijke groet, Fatima": "data:audio/mpeg;base64,"};
